import { ColorScheme, createStyleRegistry, StyleObject } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsTypeError(action: () => void, message: string): void {
  try { action(); } catch (error) { if (error instanceof TypeError) return; throw new Error(`${message}: wrong error`); }
  throw new Error(`${message}: did not throw`);
}

const nested: StyleObject = { foreground: 'red', weight: 500, enabled: true, reset: null };
const palette: StyleObject = { primary: nested, empty: {} };
const scheme: ColorScheme = { palette };
const rules: StyleObject = { button: { padding: 4, state: 'ready' }, visible: false };
const registry = createStyleRegistry(scheme, rules);

nested.foreground = 'blue';
palette.later = 'added';
rules.visible = true;
const storedScheme = registry.getScheme();
const storedRules = registry.getRules();
equal((storedScheme.palette.primary as StyleObject).foreground, 'red', 'scheme is copied immediately');
assert(!Object.prototype.hasOwnProperty.call(storedScheme.palette, 'later'), 'later input properties are absent');
equal(storedRules.visible, false, 'rules are copied immediately');

equal(Object.keys(storedScheme.palette).join(','), 'primary,empty', 'property insertion order is preserved');
const nextScheme = registry.getScheme();
const nextRules = registry.getRules();
assert(storedScheme !== nextScheme, 'scheme getter returns a fresh wrapper');
assert(storedScheme.palette !== nextScheme.palette, 'scheme getter deep copies palette');
assert(storedRules !== nextRules, 'rules getter returns a fresh object');
(storedScheme.palette.primary as StyleObject).foreground = 'mutated';
(storedRules.button as StyleObject).padding = 99;
equal((registry.getScheme().palette.primary as StyleObject).foreground, 'red', 'getter mutation cannot affect scheme');
equal((registry.getRules().button as StyleObject).padding, 4, 'getter mutation cannot affect rules');

const nullPrototype = Object.create(null) as StyleObject;
nullPrototype.value = 'accepted';
const nullRegistry = createStyleRegistry({ palette: nullPrototype }, {});
equal(nullRegistry.getScheme().palette.value, 'accepted', 'null-prototype objects are accepted');

const withSymbol = { ordinary: 'yes' } as StyleObject;
const hiddenSymbol = Symbol('hidden');
(withSymbol as unknown as { [key: symbol]: unknown })[hiddenSymbol] = () => 1;
const symbolRegistry = createStyleRegistry({ palette: withSymbol }, {});
equal(Object.getOwnPropertySymbols(symbolRegistry.getScheme().palette).length, 0, 'symbol properties are not copied');

const malformed: unknown[] = [
  { bad: [1, 2] },
  { bad: Infinity },
  { bad: NaN },
  { bad: undefined },
  { bad: () => 1 },
  { bad: new Date(0) },
];
for (const value of malformed) {
  throwsTypeError(() => createStyleRegistry({ palette: value as StyleObject }, {}), 'malformed palette value');
  throwsTypeError(() => createStyleRegistry({ palette: {} }, value as StyleObject), 'malformed rules value');
}

